const qs = require('./lib/index.js');

// Test 1: Original issue case
let r1 = qs.parse('a=1,2,3,4,5,6&a=7,8', { comma: true, arrayLimit: 5 });
console.log('Test 1 (original issue):', JSON.stringify(r1));
console.log('Expected: a has keys 0-7, flat object');

// Test 2: Multiple overflow appends
let r2 = qs.parse('a=1,2,3,4,5,6&a=7,8&a=9,10', { comma: true, arrayLimit: 5 });
console.log('Test 2 (multiple overflow appends):', JSON.stringify(r2));

// Test 3: Appending scalar to overflow
let r3 = qs.parse('a=1,2,3,4,5,6&a=7', { comma: true, arrayLimit: 5 });
console.log('Test 3 (scalar to overflow):', JSON.stringify(r3));

// Test 4: Without overflow (should remain as array)
let r4 = qs.parse('a=1,2&a=3,4', { comma: true, arrayLimit: 5 });
console.log('Test 4 (no overflow):', JSON.stringify(r4));

// Test 5: First append overflows
let r5 = qs.parse('a=1,2&a=3,4,5,6,7,8,9,10,11', { comma: true, arrayLimit: 5 });
console.log('Test 5 (second append causes overflow):', JSON.stringify(r5));
"

